package io.lark.column.biz;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/**
 * Business computation node.
 *
 * <p>Node ids are generated by the framework. Inputs are typed
 * {@link ColumnStream}s passed to the constructor, and outputs are typed
 * streams declared with {@link #fetch(Class)}. There are no string names or
 * positional indexes in business compute code:
 *
 * <pre>{@code
 * final class AmountToYuanNode
 *         extends UnaryNode<AmountFen, AmountYuan> {
 *
 *     AmountToYuanNode(AmountFen input) {
 *         super(input, AmountYuan.class);
 *     }
 *
 *     protected Tensor compute(ColumnContext ctx, Tensor input) {
 *         return Compute.divScalar(input, 100.0);
 *     }
 * }
 * }</pre>
 *
 * <p>Feeds and fetches are exposed as arrays because their arity is fixed once
 * the node is constructed.
 */
public abstract class ColumnNode {

    private final String id = NodeIds.next(getClass());
    private final ColumnStream<?>[] feeds;
    private final List<ColumnStream<?>> fetchBuilder = new ArrayList<>();
    private ColumnStream<?>[] fetches;

    protected ColumnNode(ColumnStream<?>... feeds) {
        this.feeds = feeds == null ? new ColumnStream<?>[0] : feeds;
        for (ColumnStream<?> feed : this.feeds) {
            Objects.requireNonNull(feed, "feed stream");
        }
    }

    public final String id() {
        return id;
    }

    /** Fixed input streams, in constructor order. Prefer typed fields. */
    public final ColumnStream<?>[] feeds() {
        return feeds;
    }

    /** Declared output streams, in declaration order. */
    public final ColumnStream<?>[] fetches() {
        if (fetches == null) {
            fetches = fetchBuilder.toArray(ColumnStream<?>[]::new);
        }
        return fetches;
    }

    /**
     * Declare a typed fetch output. The column class defines its name and
     * dtype; the framework binds it to this node.
     */
    protected final <T extends ColumnStream<?>> T fetch(Class<T> type) {
        return fetch(ColumnStreams.create(type));
    }

    /** Alternate form for columns that need constructor arguments. */
    protected final <T extends ColumnStream<?>> T fetch(T stream) {
        Objects.requireNonNull(stream, "stream");
        stream.bindProducer(this);
        fetchBuilder.add(stream);
        fetches = null;
        return stream;
    }

    /** Business computation; read/write typed streams via {@link ColumnContext}. */
    public abstract void compute(ColumnContext ctx);

    /**
     * Optional degradation hook invoked when {@link #compute} fails.
     *
     * @return {@code true} if a usable degraded result was written
     */
    public boolean fallback(ColumnContext ctx, Throwable error) {
        return false;
    }

    @Override
    public String toString() {
        return id + Arrays.toString(fetches());
    }
}
